// ServerInterface represents all server handlers.
type ServerInterface interface {

	// (GET /admin/settings)
	AdminGetSettings(w http.ResponseWriter, r *http.Request)

	// (PATCH /admin/settings)
	AdminUpdateSettings(w http.ResponseWriter, r *http.Request)

	// (GET /admin/users)
	AdminListUsers(w http.ResponseWriter, r *http.Request)
	// AdminCreateUser Instance admins create an account directly. Give a `password`, or omit it to get a one-time
	// set-password link (valid 7 days) to hand to the person. Optional `memberships` add the user to workspaces
	// in which the caller is owner/admin (no other workspace can be targeted).
	// (POST /admin/users)
	AdminCreateUser(w http.ResponseWriter, r *http.Request)
	// AdminUpdateUser Disable/enable a user or change instance-admin flag (cannot demote/disable the last admin or yourself)
	// (PATCH /admin/users/{userId})
	AdminUpdateUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// AdminCreateResetLink Create a one-time password-reset link (valid 24h) to hand to the user
	// (POST /admin/users/{userId}/reset-link)
	AdminCreateResetLink(w http.ResponseWriter, r *http.Request, userId UserId)
	// GetInviteInfo Look up an invite (public) to render the sign-up page
	// (GET /auth/invites/{token})
	GetInviteInfo(w http.ResponseWriter, r *http.Request, token string)
	// AcceptInvite Accept an invite as the already-logged-in user (joins the workspace)
	// (POST /auth/invites/{token})
	AcceptInvite(w http.ResponseWriter, r *http.Request, token string)

	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)

	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)

	// (GET /auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)

	// (GET /auth/oidc/callback)
	OidcCallback(w http.ResponseWriter, r *http.Request, params OidcCallbackParams)
	// OidcLogin Redirects (302) to the OIDC provider. 404 if OIDC is not configured.
	// (GET /auth/oidc/login)
	OidcLogin(w http.ResponseWriter, r *http.Request, params OidcLoginParams)

	// (POST /auth/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// ConfirmPasswordReset Set a new password using an admin-issued reset token
	// (POST /auth/password-reset/confirm)
	ConfirmPasswordReset(w http.ResponseWriter, r *http.Request)

	// (PATCH /auth/profile)
	UpdateProfile(w http.ResponseWriter, r *http.Request)
	// Register Register with an invite token, or without one if open signup is enabled
	// (POST /auth/register)
	Register(w http.ResponseWriter, r *http.Request)

	// (GET /auth/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)

	// (DELETE /auth/sessions/{sessionId})
	RevokeSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// ListApiTokens The caller's own access tokens (never includes the secret). Session-authenticated only.
	// (GET /auth/tokens)
	ListApiTokens(w http.ResponseWriter, r *http.Request)
	// CreateApiToken Create an access token for MCP clients / agents acting as the caller. The secret is returned ONCE.
	// Session-authenticated only (a token can never create tokens).
	// (POST /auth/tokens)
	CreateApiToken(w http.ResponseWriter, r *http.Request)

	// (DELETE /auth/tokens/{tokenId})
	RevokeApiToken(w http.ResponseWriter, r *http.Request, tokenId openapi_types.UUID)

	// (POST /comment-threads/{threadId}/comments)
	ReplyToThread(w http.ResponseWriter, r *http.Request, threadId ThreadId)

	// (POST /comment-threads/{threadId}/reopen)
	ReopenThread(w http.ResponseWriter, r *http.Request, threadId ThreadId)

	// (POST /comment-threads/{threadId}/resolve)
	ResolveThread(w http.ResponseWriter, r *http.Request, threadId ThreadId)
	// DeleteComment Author or `full` on the page. Deleting the last comment deletes the thread.
	// (DELETE /comments/{commentId})
	DeleteComment(w http.ResponseWriter, r *http.Request, commentId openapi_types.UUID)
	// UpdateComment Author only
	// (PATCH /comments/{commentId})
	UpdateComment(w http.ResponseWriter, r *http.Request, commentId openapi_types.UUID)
	// DownloadFile Stream a file (access rules in conventions §7). Supports Range and ETag.
	// (GET /files/{fileId})
	DownloadFile(w http.ResponseWriter, r *http.Request, fileId FileId)

	// (GET /import-jobs/{jobId})
	GetImportJob(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID)
	// GetInstanceInfo Public instance info (needs setup? signup policy? OIDC?)
	// (GET /instance/info)
	GetInstanceInfo(w http.ResponseWriter, r *http.Request)
	// PurgePage Permanently delete an archived page and its subtree (needs `full`)
	// (DELETE /pages/{pageId})
	PurgePage(w http.ResponseWriter, r *http.Request, pageId PageId)

	// (GET /pages/{pageId})
	GetPage(w http.ResponseWriter, r *http.Request, pageId PageId)
	// UpdatePage Update title/icon/cover (needs `edit`)
	// (PATCH /pages/{pageId})
	UpdatePage(w http.ResponseWriter, r *http.Request, pageId PageId)
	// ArchivePage Move the subtree to trash (needs `full`)
	// (POST /pages/{pageId}/archive)
	ArchivePage(w http.ResponseWriter, r *http.Request, pageId PageId)
	// GetBacklinks Visible pages that link to this page
	// (GET /pages/{pageId}/backlinks)
	GetBacklinks(w http.ResponseWriter, r *http.Request, pageId PageId)
	// CreateCollabToken Short-lived JWT for the collaboration WebSocket (see conventions §6). Needs `view`.
	// (POST /pages/{pageId}/collab-token)
	CreateCollabToken(w http.ResponseWriter, r *http.Request, pageId PageId)

	// (GET /pages/{pageId}/comments)
	ListCommentThreads(w http.ResponseWriter, r *http.Request, pageId PageId, params ListCommentThreadsParams)
	// CreateCommentThread Start a thread on a block (needs `comment`)
	// (POST /pages/{pageId}/comments)
	CreateCommentThread(w http.ResponseWriter, r *http.Request, pageId PageId)
	// GetPageContent Last extracted content (blocks JSON + markdown). May lag the live Y.Doc by a few seconds. Needs `view`.
	// (GET /pages/{pageId}/content)
	GetPageContent(w http.ResponseWriter, r *http.Request, pageId PageId)
	// DuplicatePage Copy the page (and optionally its subtree) next to the original. Copies page_documents/page_content rows. Needs `view` on source, `edit` on destination.
	// (POST /pages/{pageId}/duplicate)
	DuplicatePage(w http.ResponseWriter, r *http.Request, pageId PageId)
	// ExportPage Zip of the page subtree as Markdown files + attachments (format in conventions §8). Needs `view`; pages the caller can't view are skipped.
	// (GET /pages/{pageId}/export)
	ExportPage(w http.ResponseWriter, r *http.Request, pageId PageId)

	// (DELETE /pages/{pageId}/favorite)
	RemoveFavorite(w http.ResponseWriter, r *http.Request, pageId PageId)

	// (PUT /pages/{pageId}/favorite)
	AddFavorite(w http.ResponseWriter, r *http.Request, pageId PageId)
	// MovePage Reparent/reorder. Needs `edit` on the page and on the destination parent. Omit afterId/beforeId to append.
	// (POST /pages/{pageId}/move)
	MovePage(w http.ResponseWriter, r *http.Request, pageId PageId)
	// GetPagePermissions Explicit grants (own + inherited) and visibility. Needs `full`.
	// (GET /pages/{pageId}/permissions)
	GetPagePermissions(w http.ResponseWriter, r *http.Request, pageId PageId)
	// GrantPagePermission Grant (or change) a user's role on this page. Needs `full`. Identify the user by `userId` or `email`.
	// If the user exists on the instance but is not in the workspace, they are added as `guest`.
	// Unknown email → 404 (UI then offers a guest invite).
	// (POST /pages/{pageId}/permissions)
	GrantPagePermission(w http.ResponseWriter, r *http.Request, pageId PageId)

	// (DELETE /pages/{pageId}/permissions/{userId})
	RevokePagePermission(w http.ResponseWriter, r *http.Request, pageId PageId, userId UserId)
	// RestorePage Restore an archived subtree (needs `full`). If the parent is archived/missing, restores to top level.
	// (POST /pages/{pageId}/restore)
	RestorePage(w http.ResponseWriter, r *http.Request, pageId PageId)
	// ListShareLinks Active public links of the page. Needs `full`.
	// (GET /pages/{pageId}/shares)
	ListShareLinks(w http.ResponseWriter, r *http.Request, pageId PageId)

	// (POST /pages/{pageId}/shares)
	CreateShareLink(w http.ResponseWriter, r *http.Request, pageId PageId)
	// SetPageVisibility Root pages only (422 for child pages). Needs `full`.
	// (PUT /pages/{pageId}/visibility)
	SetPageVisibility(w http.ResponseWriter, r *http.Request, pageId PageId)
	// DownloadPublicFile File from the shared workspace subtree; same serving rules as /files/{fileId}
	// (GET /public/{token}/files/{fileId})
	DownloadPublicFile(w http.ResponseWriter, r *http.Request, token ShareToken, fileId FileId)
	// GetPublicPage The shared root page (read-only). Never exposes emails or user ids.
	// (GET /public/{token}/page)
	GetPublicPage(w http.ResponseWriter, r *http.Request, token ShareToken)
	// GetPublicSubpage A descendant of the shared page (only when includeSubpages is true)
	// (GET /public/{token}/pages/{pageId})
	GetPublicSubpage(w http.ResponseWriter, r *http.Request, token ShareToken, pageId PageId)
	// SetupInstance Create the first user (instance admin) and a default workspace. 409 once any user exists.
	// (POST /setup)
	SetupInstance(w http.ResponseWriter, r *http.Request)

	// (DELETE /shares/{shareId})
	RevokeShareLink(w http.ResponseWriter, r *http.Request, shareId openapi_types.UUID)

	// (PATCH /shares/{shareId})
	UpdateShareLink(w http.ResponseWriter, r *http.Request, shareId openapi_types.UUID)

	// (GET /workspaces)
	ListWorkspaces(w http.ResponseWriter, r *http.Request)
	// CreateWorkspace Allowed for instance admins, and for everyone when allowWorkspaceCreation is true
	// (POST /workspaces)
	CreateWorkspace(w http.ResponseWriter, r *http.Request)
	// DeleteWorkspace Owner only. Cascades all pages and files.
	// (DELETE /workspaces/{workspaceId})
	DeleteWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)

	// (GET /workspaces/{workspaceId})
	GetWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// UpdateWorkspace Owner/admin only
	// (PATCH /workspaces/{workspaceId})
	UpdateWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// SubscribeEvents Server-sent events stream (see conventions §5)
	// (GET /workspaces/{workspaceId}/events)
	SubscribeEvents(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ExportWorkspace Zip of all pages the caller can view
	// (GET /workspaces/{workspaceId}/export)
	ExportWorkspace(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)

	// (GET /workspaces/{workspaceId}/favorites)
	ListFavorites(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// UploadFile Upload an image/file (multipart). Needs `edit` on `pageId` when given, else workspace membership (non-guest).
	// (POST /workspaces/{workspaceId}/files)
	UploadFile(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// GetGraph Link graph of pages the caller can view (edges only between visible nodes)
	// (GET /workspaces/{workspaceId}/graph)
	GetGraph(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ImportZip Import a zip of Markdown files (Obsidian vault compatible). Runs async. Needs `edit` on parentId (or workspace membership for top level).
	// (POST /workspaces/{workspaceId}/import)
	ImportZip(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// ListInvites Owner/admin only. Pending (unused, unexpired) invites.
	// (GET /workspaces/{workspaceId}/invites)
	ListInvites(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// CreateInvite Owner/admin only
	// (POST /workspaces/{workspaceId}/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)

	// (DELETE /workspaces/{workspaceId}/invites/{inviteId})
	RevokeInvite(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, inviteId openapi_types.UUID)

	// (GET /workspaces/{workspaceId}/members)
	ListMembers(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// AddMember Add an existing account to the workspace (owner/admin only; only owners may add admins). Identify the
	// user by `userId` or `email`. Unknown email → 404 (the UI then offers an invite link). Already a member → 409.
	// (POST /workspaces/{workspaceId}/members)
	AddMember(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// RemoveMember Remove a member (or leave, when userId is the caller). Cannot remove the last owner.
	// (DELETE /workspaces/{workspaceId}/members/{userId})
	RemoveMember(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, userId UserId)
	// UpdateMember Change role. Owner/admin only; only owners can grant/revoke owner; cannot remove the last owner.
	// (PATCH /workspaces/{workspaceId}/members/{userId})
	UpdateMember(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, userId UserId)
	// ListPages Flat list of every non-archived page the caller can view (client builds the tree)
	// (GET /workspaces/{workspaceId}/pages)
	ListPages(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
	// CreatePage Create a page. `id` may be a client-generated UUIDv7 (idempotent: same id + same creator returns 200 with the existing page).
	// (POST /workspaces/{workspaceId}/pages)
	CreatePage(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)

	// (GET /workspaces/{workspaceId}/recent)
	ListRecentPages(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params ListRecentPagesParams)

	// (GET /workspaces/{workspaceId}/search)
	Search(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId, params SearchParams)
	// ListTrash Archived subtree roots the caller has `full` on
	// (GET /workspaces/{workspaceId}/trash)
	ListTrash(w http.ResponseWriter, r *http.Request, workspaceId WorkspaceId)
}

